import {
  Component,
  h,
  Prop,
  Event,
  EventEmitter,
  Watch,
  ComponentInterface,
  Element,
  State,
  Host,
} from '@stencil/core';
import { KsIconChevronLeft, KsIconChevronRight } from '@fe-infra/keystone-icons-stencil';
import { Slot, type Slots, Uncontrollable } from '@src/framework/decorators';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { TabsLayoutController } from './tabs-layout.controller';
import type { TabSize, TabType, TabPosition } from './types';

const prefix = 'tabs';

/**
 * @slot default - Tab items that define the tab headers and panel content.
 * @slot tabBarExtraContent - Slot for extra content to be displayed on the right side of the tab bar.
 * @part header - The header container.
 * @part base - The base container of the component.
 * @part divider - The divider rendered between the tab bar and the content area in the `default` type.
 * @part content - The content container.
 * @part item - Each tab trigger button in the tab bar.
 * @part itemActive - The active tab trigger button in the tab bar.
 */
@Component({
  tag: 'ks-tabs',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsTabs implements ComponentInterface {
  private readonly layoutController = new TabsLayoutController({
    getHostElement: () => this.el,
    isHorizontal: () => this.direction === 'horizontal',
    onOverflowStateChange: ({ hasHorizontalOverflow, isAtPhysicalLeft, isAtPhysicalRight }) => {
      this.hasHorizontalOverflow = hasHorizontalOverflow;
      this.isAtPhysicalLeft = isAtPhysicalLeft;
      this.isAtPhysicalRight = isAtPhysicalRight;
    },
    onChildrenChange: () => this.renderSlotContent(),
  });

  @State() private hasHorizontalOverflow = false;
  @State() private isAtPhysicalLeft = true;
  @State() private isAtPhysicalRight = true;

  @Element() el!: HTMLKsTabsElement;

  @Uncontrollable('activeTabId', 'defaultActiveTabId', 'ksActiveTabIdChange') @State() internalActiveTabId?: string;
  @Watch('internalActiveTabId')
  protected internalActiveTabIdChanged() {
    this.renderSlotContent();
  }

  /** The size of the tabs. Can be one of the following values: `"md"`, `"lg"`. */
  @Prop() size: TabSize = 'md';
  /** The ID of the currently active tab. Controls which tab is displayed. */
  @Prop() activeTabId?: string;
  /** The default ID of the currently active tab. Controls which tab is displayed. */
  @Prop() defaultActiveTabId = '';
  /** The position of the tabs. Can be one of the following values: `top`, `bottom`, `left`, `right`. */
  @Prop() tabPosition: TabPosition = 'top';
  @Watch('tabPosition')
  protected tabPositionChanged() {
    this.layoutController.refresh();
  }
  /** The type of tabs, which defines the style and behavior of the tabs. Can be one of the following values: `"default"`, `lite`, `sub-tab`. */
  @Prop() type: TabType = 'default';
  /** Indicates whether the tabs are disabled. When `true`, the tabs are not interactive. */
  @Prop() disabled = false;
  /**
   * @private Internal prop for dropdown usage, please don't use. */
  @Prop() __dropdownHeaderSticky = false;

  /** Triggered when the active tab changes. Emits the `tabId` of the newly active tab. */
  @Event({ bubbles: false, composed: false }) ksActiveTabIdChange!: EventEmitter<string>;

  @Slot({
    slotname: '_default',
    filter: (node?: Element) => node?.classList.contains('KsTabItem') ?? false,
  })
  private children?: Slots<HTMLKsTabItemElement>;

  constructor() {
    registerPluginManager(this.el);
  }

  get direction() {
    return this.tabPosition === 'left' || this.tabPosition === 'right' ? 'vertical' : 'horizontal';
  }

  get correctTabPosition() {
    if (this.direction === 'vertical' && getComputedStyle(this.el).direction === 'rtl') {
      if (this.tabPosition === 'left') {
        return 'right';
      } else if (this.tabPosition === 'right') {
        return 'left';
      }
    }
    return this.tabPosition;
  }

  connectedCallback() {
    this.layoutController.connect();
  }

  componentDidLoad() {
    this.renderSlotContent();
    this.layoutController.setup();
  }

  componentDidRender() {
    this.layoutController.afterRender();
  }

  disconnectedCallback(): void {
    this.layoutController.disconnect();
  }

  private handleClick = (item: HTMLKsTabItemElement) => () => {
    if (this.disabled || item.disabled) {
      return;
    }

    this.internalActiveTabId = item.tabId;
    sendActionTracking(this.el, { eventType: 'click', componentParams: { id: item.tabId } });
  };

  private handleKeydown = (event: KeyboardEvent) => {
    const tabElements = this.layoutController.getTabElements();
    let flag = false;

    switch (event.key) {
      case 'ArrowLeft':
        this.moveFocusToPreviousTab(event.currentTarget, tabElements);
        flag = true;
        break;

      case 'ArrowRight':
        this.moveFocusToNextTab(event.currentTarget, tabElements);
        flag = true;
        break;

      case 'Home':
        tabElements[0]?.focus();
        flag = true;
        break;

      case 'End':
        tabElements[tabElements.length - 1]?.focus();
        flag = true;
        break;

      default:
        break;
    }

    if (flag) {
      event.stopPropagation();
      event.preventDefault();
    }
  };

  private moveFocusToPreviousTab(currentTab: EventTarget | null, tabElements: HTMLElement[]) {
    if (!currentTab) return;

    const index = tabElements.indexOf(currentTab as HTMLElement);
    if (index < 1) {
      tabElements[tabElements.length - 1]?.focus();
    } else {
      tabElements[index - 1]?.focus();
    }
  }

  private moveFocusToNextTab(currentTab: EventTarget | null, tabElements: HTMLElement[]) {
    if (!currentTab) return;

    const index = tabElements.indexOf(currentTab as HTMLElement);

    tabElements[(index + 1) % tabElements.length]?.focus();
  }

  private renderScrollControl(direction: 'left' | 'right') {
    const isLeft = direction === 'left';
    return (
      <ks-icon-button
        class={`${prefix}__scroll-control`}
        size="sm"
        variant="text"
        disabled={isLeft ? this.isAtPhysicalLeft : this.isAtPhysicalRight}
        data-tabs-scroll={direction}
        onClick={() => this.layoutController.scrollByViewport(direction)}
      >
        {isLeft ? <KsIconChevronLeft aria-hidden="true" /> : <KsIconChevronRight aria-hidden="true" />}
        <span class={`${prefix}__scroll-label`}>Scroll tabs {direction}</span>
      </ks-icon-button>
    );
  }

  private renderTabHeader() {
    return (
      <div
        class={{
          [`${prefix}__bar`]: true,
          [`${prefix}__bar--${this.type}`]: true,
        }}
        part="header"
      >
        {/*  tab 头部  */}
        <div class={`${prefix}__bar-navigation`}>
          {this.direction === 'horizontal' && this.hasHorizontalOverflow && this.renderScrollControl('left')}
          <div class={`${prefix}__bar-content`} ref={this.layoutController.setViewport} role="tablist">
            {this.children?.map((item) => {
              const isActive = item.tabId === this.internalActiveTabId;
              const isDisabled = this.disabled || item.disabled;
              const ariaAttributes = Object.assign(
                {
                  role: 'tab',
                  'aria-selected': `${isActive}`,
                },
                !isActive ? { tabindex: -1 } : undefined,
              );
              return (
                <button
                  {...ariaAttributes}
                  data-tab-item={item.tabId}
                  onClick={this.handleClick(item)}
                  onKeyDown={this.handleKeydown}
                  part={isActive ? 'item itemActive' : 'item'}
                  class={{
                    [`${prefix}__bar-item`]: true,
                    [`${prefix}__bar-item--${this.size}`]: true,
                    [`${prefix}__bar-item--active`]: isActive,
                    [`${prefix}__bar-item--disabled`]: isDisabled,
                  }}
                  data-testid="ks-tabs-index-m22yjM"
                >
                  <slot name={item.tabId}></slot>
                </button>
              );
            })}
          </div>
          {this.direction === 'horizontal' && this.hasHorizontalOverflow && this.renderScrollControl('right')}
        </div>
        {/* 右边额外元素 */}
        <div class={`${prefix}__bar-extra`}>
          <slot name="tabBarExtraContent"></slot>
        </div>
      </div>
    );
  }

  private renderSlotContent() {
    this.children?.forEach((item) => {
      item.toggleAttribute('hidden', this.internalActiveTabId !== item.tabId);
    });
  }

  render() {
    return (
      <Host class="KsTabs">
        <div
          class={{
            [prefix]: true,
            [`${prefix}__wrapper`]: true,
            [`${prefix}--${this.tabPosition}`]: true,
            [`${prefix}--${this.direction}`]: true,
          }}
          part="base"
        >
          <div
            class={{
              [prefix]: true,
              [`${prefix}--${this.tabPosition}`]: true,
              [`${prefix}--${this.direction}`]: true,
              [`${prefix}--sticky`]: this.__dropdownHeaderSticky,
            }}
          >
            {/*  tab 头部  */}
            {this.renderTabHeader()}
            {/*  分割线  */}
            {this.type === 'default' && (
              <ks-divider
                orientation={this.direction}
                style={{ [`margin-${this.correctTabPosition}`]: '-1px' }}
                part="divider"
              />
            )}
          </div>
          {/*  tab 内容区  */}
          <div class={`${prefix}__content`} part="content">
            <slot></slot>
          </div>
        </div>
      </Host>
    );
  }
}
