const scrollEdgeEpsilon = 1;

export interface TabsOverflowState {
  hasHorizontalOverflow: boolean;
  isAtPhysicalLeft: boolean;
  isAtPhysicalRight: boolean;
}

export interface TabsLayoutControllerHost {
  getHostElement: () => HTMLElement;
  isHorizontal: () => boolean;
  onOverflowStateChange: (state: TabsOverflowState) => void;
  onChildrenChange: () => void;
}

const noHorizontalOverflow: TabsOverflowState = {
  hasHorizontalOverflow: false,
  isAtPhysicalLeft: true,
  isAtPhysicalRight: true,
};

export class TabsLayoutController {
  private viewport: HTMLDivElement | null = null;
  private listeningViewport: HTMLDivElement | null = null;
  private tabElements: HTMLElement[] = [];
  private resizeObserver: ResizeObserver | null = null;
  private mutationObserver: MutationObserver | null = null;
  private connected = false;
  private initialized = false;
  private shouldRefreshAfterRender = false;
  private refreshScheduled = false;
  private generation = 0;

  constructor(private readonly host: TabsLayoutControllerHost) {}

  connect() {
    this.connected = true;
    if (this.initialized) this.start();
  }

  setup() {
    this.initialized = true;
    this.start();
  }

  disconnect() {
    this.connected = false;
    this.generation += 1;
    this.refreshScheduled = false;
    this.resizeObserver?.disconnect();
    this.mutationObserver?.disconnect();
    this.listeningViewport?.removeEventListener('scroll', this.sync);
    this.listeningViewport = null;
    this.resizeObserver = null;
    this.mutationObserver = null;
  }

  setViewport = (viewport?: HTMLDivElement | null) => {
    if (!viewport || viewport === this.viewport) return;

    this.viewport = viewport;
    this.collectTabElements();
    if (!this.connected) return;

    this.listenToViewport();
    this.scheduleRefresh();
  };

  afterRender() {
    this.collectTabElements();
    if (!this.shouldRefreshAfterRender) return;

    this.shouldRefreshAfterRender = false;
    this.scheduleRefresh();
  }

  refresh() {
    this.refreshObservedElements();
    this.sync();
    this.shouldRefreshAfterRender = true;
    this.scheduleRefresh();
  }

  sync = () => {
    const viewport = this.viewport;
    if (!viewport || !this.host.isHorizontal()) {
      this.host.onOverflowStateChange(noHorizontalOverflow);
      return;
    }

    const { clientWidth, scrollLeft, scrollWidth } = viewport;
    const stableClientWidth = Math.max(clientWidth, viewport.parentElement?.clientWidth ?? 0);
    const maxScroll = Math.max(0, scrollWidth - clientWidth);
    const hasHorizontalOverflow = scrollWidth - stableClientWidth > scrollEdgeEpsilon;
    const isRtl = getComputedStyle(viewport).direction === 'rtl';
    const physicalFromLeft = Math.min(maxScroll, Math.max(0, isRtl ? maxScroll + scrollLeft : scrollLeft));

    this.host.onOverflowStateChange({
      hasHorizontalOverflow,
      isAtPhysicalLeft: !hasHorizontalOverflow || physicalFromLeft <= scrollEdgeEpsilon,
      isAtPhysicalRight: !hasHorizontalOverflow || physicalFromLeft >= maxScroll - scrollEdgeEpsilon,
    });
  };

  getTabElements() {
    this.collectTabElements();
    return this.tabElements;
  }

  scrollByViewport(direction: 'left' | 'right') {
    if (!this.viewport) return;

    this.viewport.scrollBy({
      left: (direction === 'left' ? -1 : 1) * this.viewport.clientWidth,
      behavior: 'smooth',
    });
  }

  private start() {
    if (!this.connected) return;

    this.resizeObserver ??= new ResizeObserver(this.sync);
    this.refreshObservedElements();
    this.listenToViewport();

    this.mutationObserver?.disconnect();
    this.mutationObserver ??= new MutationObserver((mutations) => {
      if (!mutations.some((mutation) => mutation.type === 'childList')) return;

      this.shouldRefreshAfterRender = true;
      this.host.onChildrenChange();
    });
    this.mutationObserver.observe(this.host.getHostElement(), { childList: true });
    this.sync();
  }

  private collectTabElements() {
    this.tabElements = Array.from(this.viewport?.querySelectorAll<HTMLElement>('[role=tab]') ?? []);
  }

  private refreshObservedElements() {
    this.collectTabElements();
    this.resizeObserver?.disconnect();
    if (!this.viewport || !this.host.isHorizontal()) return;

    this.resizeObserver?.observe(this.host.getHostElement());
    this.resizeObserver?.observe(this.viewport);
    this.tabElements.forEach((tabElement) => this.resizeObserver?.observe(tabElement));
  }

  private listenToViewport() {
    if (this.listeningViewport === this.viewport) return;

    this.listeningViewport?.removeEventListener('scroll', this.sync);
    this.viewport?.addEventListener('scroll', this.sync);
    this.listeningViewport = this.viewport;
  }

  private scheduleRefresh() {
    if (this.refreshScheduled) return;

    this.refreshScheduled = true;
    const scheduledGeneration = this.generation;
    queueMicrotask(() => {
      if (scheduledGeneration !== this.generation) return;

      this.refreshScheduled = false;
      if (!this.connected) return;
      this.refreshObservedElements();
      this.sync();
    });
  }
}
